SELECT sm.store_nm AS store_nm, '' AS user_name, CAST(NULL AS VARCHAR(100)) AS user_id, am.act_dt AS act_dt, COUNT(am.act_idx) AS cnt FROM store_mst sm LEFT OUTER JOIN active_mst am ON sm.store_idx = am.store_idx AND (am.appr_status = 'PENDING' OR am.appr_status = 'APPROVED') AND am.act_dt BETWEEN #{startDt} AND #{endDt} WHERE 1 = 1
AND sm.brand_cd = #{brandCd}
GROUP BY sm.store_nm, am.act_dt ORDER BY sm.store_nm, am.act_dt

SELECT user_id, user_name FROM user_mst
WHERE user_id IN

    #{id}

SELECT c.chk_idx, c.brand_cd, c.chk_type, COALESCE(cm.code_nm, c.chk_type) AS chk_type_nm, c.chk_content, c.base_score, c.use_yn, c.display_order FROM chk_mst c LEFT JOIN code_mst cm ON cm.grp_cd = '50' AND cm.code_cd = c.chk_type WHERE 1 = 1
AND c.brand_cd = #{brandCd}
AND c.chk_type = #{chkType}
ORDER BY c.chk_type

SELECT user_id, CAST((create_dt AT TIME ZONE 'Asia/Seoul') AS DATE) AS create_day FROM notif_mst WHERE act_idx = #{actIdx} AND notif_typ = #{notifTyp}
AND appr_yn = 'Y'
ORDER BY notif_idx ASC

SELECT user_id, CAST(create_dt AS DATE) AS create_day FROM notif_mst WHERE act_idx = #{actIdx} AND notif_typ = #{notifTyp}
AND appr_yn = 'Y'
ORDER BY notif_idx ASC

